frappe.ui.form.on('Sales Invoice', {
    refresh: function(frm) {
        if (frm.doc.docstatus === 1) {  // Only show when submitted
            frm.add_custom_button('Send via WhatsApp', () => {

                frappe.call({
                    method: 'erpnext.accounts.doctype.sales_invoice.sales_invoice.send_invoice_whatsapp',
                    args: {
                      invoice_name: frm.doc.name

                    },
                    callback: function(r) {
                        console.log(r.message_status)
                        frappe.msgprint("Whatsapp Message Sent Successfully")
                    }
                });
            });
        }
    }
});

frappe.ui.form.on('Item Group Rate Master', {
	item_group: function(frm) {
        if (frm.doc.item_group) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'Item Group',
                    filters: {
                        name: frm.doc.item_group
                    },
                    fieldname: 'price'
                },
                callback: function(r) {
                    if (r.message) {
                        price_total=frm.doc.price_master + r.message.price
                        frm.set_value('price_master', price_total);
                    }
                }
            });
        }
    }
})

frappe.ui.form.on('Sales Order Item', {
  item_code: function(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (row.item_code ) {
      frappe.call({
        method: "frappe.client.get_value",
        args: {
          doctype: "Bin",
          filters: {
            item_code: row.item_code

          },
          fieldname: "actual_qty"
        },
        callback: function(r) {
            console.log("r.message.actual_qty::"+r.message.actual_qty)
          if (r.message) {
            frappe.model.set_value(cdt, cdn, "available_stock", r.message.actual_qty);
          } else {
            frappe.model.set_value(cdt, cdn, "available_stock", 0);
          }
        }
      });
    }
  },

});

frappe.ui.form.on("Sales Order", {
  refresh: function(frm) {
      frm.__original_company = frm.doc.company;
    if (frm.doc.docstatus === 0) {
      frm.add_custom_button("Select from Available Stock", () => {
             gajanand.stock_selector.show_stock_dialog(frm);
      });
    }
  }

});
frappe.ui.form.on('Sales Order', {
  onload(frm) {
    // Store initial company value
    frm.__original_company = frm.doc.company;
  }

});

frappe.ui.form.on('Sales Order', {
  company: function (frm) {
    if (frm.__original_company &&
      frm.doc.company !== frm.__original_company && frm.doc.items && frm.doc.items.length > 0) {
      frappe.msgprint({
        title: __('Company Changed'),
        message: __('Items have been cleared because the company was changed. Please reselect stock.'),
        indicator: 'orange'
      });
      frm.clear_table('items');
      frm.refresh_field('items');
    }
  }
});

